'use strict';
(() => {
  const el = id => document.getElementById(id);
  const sizes = {A4:{w:210,h:297,cols:1,rows:1},A5:{w:297,h:210,cols:2,rows:1},A6:{w:210,h:297,cols:2,rows:2},A7:{w:297,h:210,cols:4,rows:2}};
  const note = 'يشترط أن يكون المنتجان مربوطين معًا في ربطة واحدة.';
  const data = {brand:'nozha',size:'A4',mono:false,active:false};
  const params = new URL(location.href).searchParams;
  if (['nozha','karaz'].includes(params.get('brand'))) data.brand=params.get('brand');
  if (sizes[params.get('size')]) data.size=params.get('size');
  data.mono=params.get('output')==='mono';
  let busy=false,logoId=0;
  const tab=document.createElement('button');tab.type='button';tab.id='bundleMode';tab.role='tab';tab.setAttribute('aria-controls','bundleWorkspace');tab.setAttribute('aria-selected','false');tab.textContent='١ + ١ مجانًا';document.querySelector('.mode-navigation').append(tab);
  const root=document.createElement('main');root.id='bundleWorkspace';root.className='bundle-workspace';root.hidden=true;root.dir='rtl';
  root.innerHTML=`<header class="bundle-intro"><div><span class="bundle-eyebrow">تصميم العروض الداخلية</span><h1>واحد + واحد مجانًا</h1><p>تصميم مستقل لكل علامة، جاهز للطباعة على ورق أبيض.</p></div><span class="bundle-intro-mark" dir="ltr" aria-hidden="true">1 + 1</span></header><div class="bundle-layout"><aside class="bundle-controls"><section><h2>العلامة التجارية</h2><div class="bundle-brands" role="group" aria-label="علامة عرض واحد زائد واحد"><button type="button" data-bundle-brand="nozha" aria-pressed="false"><span class="brand-art nozha-art"><img src="assets/nozha.jpg" alt="شعار نزهة الأصلي"></span><b>نزهة</b></button><button type="button" data-bundle-brand="karaz" aria-pressed="false"><span class="brand-art karaz-art"><img src="assets/karaz.jpg" alt="شعار كرز الأصلي"></span><b>كرز</b></button></div></section><section><h2>مقاس البطاقة</h2><div class="bundle-sizes" role="group" aria-label="مقاس عرض واحد زائد واحد">${Object.entries(sizes).map(([size,g])=>`<button type="button" data-bundle-size="${size}" aria-pressed="false"><strong dir="ltr">${size}</strong><span>${g.cols*g.rows===1?'بطاقة واحدة':g.cols*g.rows===2?'بطاقتان':g.cols*g.rows===4?'٤ بطاقات':'٨ بطاقات'} على A4</span></button>`).join('')}</div><p class="bundle-stock" id="bundleStock"></p></section><section><h2>ألوان الطباعة</h2><div class="bundle-colors" role="group" aria-label="ألوان عرض واحد زائد واحد"><button type="button" data-bundle-output="color" aria-pressed="false">ملون</button><button type="button" data-bundle-output="mono" aria-pressed="false">أبيض وأسود</button></div></section><section class="bundle-condition"><span>ملاحظة العرض</span><p>${note}</p></section><div class="bundle-output"><button type="button" class="print-button" id="bundlePrint">فتح PDF للطباعة</button><button type="button" class="secondary" id="bundleDownload">تنزيل PDF</button><p>ورق A4 أبيض · الحجم الفعلي 100% · وجه واحد</p></div></aside><section class="bundle-preview"><div class="bundle-preview-head"><div><h2>معاينة الطباعة</h2><p id="bundleSummary"></p></div><span id="bundleBadge"></span></div><div class="bundle-stage"><div id="bundleFrame"><div id="bundlePreview"></div></div></div><p class="bundle-status" id="bundleStatus" role="status" aria-live="polite"></p></section></div>`;
  el('designsWorkspace').after(root);
  function geometry(){const g=sizes[data.size];return {...g,cw:g.w/g.cols,ch:g.h/g.rows,count:g.cols*g.rows};}
  function logo(){const karaz=data.brand==='karaz',view=karaz?'493 390 534 303':'74 70 1370 1180',[x,y,w,h]=view.split(' '),id='bundle-logo-'+(++logoId);return `<svg class="bundle-logo" viewBox="${view}" role="img" aria-label="شعار ${karaz?'كرز':'نزهة'}" preserveAspectRatio="xMidYMid meet"><defs><clipPath id="${id}"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath></defs><image href="assets/${data.brand}.jpg" width="1536" height="${karaz?1086:1331}" clip-path="url(#${id})"/></svg>`;}
  function card(g){return `<article class="bundle-card bundle-${data.brand}" style="--bundle-u:${g.cw/100}mm;--bundle-cw:${g.cw}mm;--bundle-ch:${g.ch}mm" aria-label="عرض واحد زائد واحد مجانًا — ${data.brand==='nozha'?'نزهة':'كرز'}"><div class="bundle-edge" aria-hidden="true"></div><header class="bundle-card-head">${logo()}<div class="bundle-special"><span>عرض خاص</span><i></i><small>توفير مضاعف</small></div></header><p class="bundle-lead">اشترِ واحدًا واحصل على الثاني</p><div class="bundle-numbers" dir="ltr" aria-label="واحد زائد واحد"><span>1</span><b>+</b><span class="bundle-second">1</span></div><div class="bundle-free"><span>مجانًا</span><i aria-hidden="true"></i></div><p class="bundle-value">حبتان بسعر حبة</p><div class="bundle-note"><svg viewBox="0 0 48 36" aria-hidden="true"><rect x="4" y="7" width="17" height="23" rx="3"/><rect x="27" y="7" width="17" height="23" rx="3"/><path d="M2 18h44M21 14l3-3 3 3M21 22l3 3 3-3"/></svg><p>${note}</p></div><footer class="bundle-card-foot"><span>الجودة</span><i>•</i><span>السعر</span><i>•</i><span>الخدمة</span></footer></article>`;}
  function sheet(){const g=geometry(),page=document.createElement('div');page.className='bundle-sheet'+(data.mono?' bundle-sheet-mono':'');page.style.cssText=`width:${g.w}mm;height:${g.h}mm;grid-template-columns:repeat(${g.cols},${g.cw}mm);grid-template-rows:repeat(${g.rows},${g.ch}mm)`;page.dataset.size=data.size;page.dataset.brand=data.brand;page.innerHTML=Array.from({length:g.count},()=>card(g)).join('');return page;}
  function syncButtons(){for(const id of ['bundlePrint','bundleDownload'])el(id).disabled=busy;if(data.active)for(const id of ['printTop','downloadTop'])el(id).disabled=busy;}
  function resize(){if(!data.active)return;const g=geometry(),scale=Math.min(.85,Math.max(120,root.querySelector('.bundle-stage').clientWidth-32)/(g.w*96/25.4));el('bundlePreview').style.transform=`scale(${scale})`;el('bundleFrame').style.width=g.w*96/25.4*scale+'px';el('bundleFrame').style.height=g.h*96/25.4*scale+'px';}
  function renderBundle(){const g=geometry();root.dataset.brand=data.brand;root.querySelectorAll('[data-bundle-output]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.bundleOutput==='mono')===data.mono)));root.querySelectorAll('[data-bundle-brand]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.bundleBrand===data.brand)));root.querySelectorAll('[data-bundle-size]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.bundleSize===data.size)));el('bundlePreview').replaceChildren(sheet());el('bundleSummary').textContent=(data.brand==='nozha'?'نزهة':'كرز')+' · '+data.size+' · '+g.count+' في الورقة · '+(data.mono?'أبيض وأسود':'ملون');el('bundleBadge').textContent='جاهز للطباعة';el('bundleStock').textContent=`البطاقة ${g.cw.toFixed(1)} × ${g.ch.toFixed(1)} مم. ورق A4 ${g.w>g.h?'أفقي':'رأسي'}.`;resize();syncButtons();}
  function updateUrl(){const url=new URL(location.href);url.searchParams.set('view','bundle');url.searchParams.set('brand',data.brand);url.searchParams.set('size',data.size);url.searchParams.set('output',data.mono?'mono':'color');history.replaceState(null,'',url);}
  function leave(){if(!data.active)return;data.active=false;root.hidden=true;document.body.classList.remove('bundle-active');tab.setAttribute('aria-selected','false');el('printRoot').replaceChildren();printPrepared=false;}
  function enter(){window.offerStudio.setMode(false);window.designStudio.leave();data.active=true;root.hidden=false;document.body.classList.add('bundle-active');el('pricesWorkspace').hidden=true;el('offersWorkspace').hidden=true;el('designsWorkspace').hidden=true;for(const id of ['pricesMode','offersMode','designsMode'])el(id).setAttribute('aria-selected','false');tab.setAttribute('aria-selected','true');updateUrl();renderBundle();}
  function prepare(){if(busy)return false;const g=geometry();el('printRoot').replaceChildren(sheet());el('printSize').textContent=`@page { size:${g.w}mm ${g.h}mm; margin:0; }`;printPrepared=true;return true;}
  async function output(forPrint=false){
    if(busy)return;
    let viewer=null;
    if(forPrint){try{viewer=window.open('about:blank','_blank');if(viewer){viewer.opener=null;viewer.document.title='تجهيز عرض 1+1';viewer.document.documentElement.dir='rtl';viewer.document.body.textContent='يجري تجهيز ملف الطباعة…';}}catch{viewer=null;}}
    busy=true;syncButtons();root.inert=true;const nav=Array.from(document.querySelectorAll('.mode-navigation button')).map(b=>[b,b.disabled]);nav.forEach(([b])=>b.disabled=true);const print=el('printRoot'),originalStyle=print.getAttribute('style');
    try{el('bundleStatus').textContent='يجري تجهيز ملف الطباعة…';await Promise.all([document.fonts.ready,window.StudioAssets.pdf()]);const g=geometry(),page=sheet();print.replaceChildren(page);Object.assign(print.style,{display:'block',position:'fixed',left:'0',top:'0',zIndex:'-1',pointerEvents:'none'});const first=page.firstElementChild;await Promise.all(Array.from(first.querySelectorAll('svg image')).map(async img=>img.setAttribute('href',await pdfAssetDataUrl(img.getAttribute('href')))));Object.assign(first.style,{position:'absolute',left:'0',top:'0'});
      // Render the shared design once, then reuse its image for each card.
      const canvas=await window.html2canvas(first,{scale:300/96,backgroundColor:'#fff',useCORS:true,logging:false,scrollX:0,scrollY:0,windowWidth:Math.max(1123,document.documentElement.clientWidth),windowHeight:Math.max(1123,document.documentElement.clientHeight),ignoreElements:element=>!!element.closest('body')&&!element.contains(first)&&!first.contains(element),onclone(doc){doc.getElementById('printRoot').style.zIndex='0';}});
      if(!canvas.width||!canvas.height)throw new Error('تعذر تجهيز صورة التصميم.');
      if(data.mono)grayscaleCanvas(canvas);
      const pdf=new window.jspdf.jsPDF({unit:'mm',format:[g.w,g.h],orientation:g.w>g.h?'landscape':'portrait',compress:true});pdf.setProperties({title:`1+1 Free — ${data.brand==='nozha'?'Nozha':'Karaz'} — ${data.size}${data.mono?' — BW':''}`,creator:'',author:''});
      for(let i=0;i<g.count;i++)pdf.addImage(canvas,'PNG',(i%g.cols)*g.cw,Math.floor(i/g.cols)*g.ch,g.cw,g.ch,'bundle-card','FAST');canvas.width=canvas.height=1;
      if(forPrint&&viewer&&!viewer.closed){const url=URL.createObjectURL(pdf.output('blob'));viewer.location.replace(url);viewer=null;setTimeout(()=>URL.revokeObjectURL(url),600000);el('bundleStatus').textContent='تم فتح ملف الطباعة. اضغط رمز الطابعة داخل PDF واختر الحجم الفعلي 100%.';}
      else{await pdf.save(`Buy1_Get1_Free_${data.brand}_${data.size}_on_A4_${data.mono?'BW':'Color'}.pdf`,{returnPromise:true});el('bundleStatus').textContent='تم تنزيل PDF. اطبعه على ورق A4 أبيض بالحجم الفعلي 100%.';}
    }catch(error){if(viewer&&!viewer.closed)viewer.close();console.error('Bundle offer PDF export failed:',error);el('bundleStatus').textContent='تعذر تجهيز الملف. تحقّق من الاتصال وأعد المحاولة.';}
    finally{print.replaceChildren();printPrepared=false;if(originalStyle===null)print.removeAttribute('style');else print.setAttribute('style',originalStyle);nav.forEach(([b,disabled])=>b.disabled=disabled);root.inert=false;busy=false;syncButtons();}
  }
  tab.onclick=enter;
  for(const id of ['pricesMode','offersMode','designsMode'])el(id).addEventListener('click',leave,true);
  document.addEventListener('pricing:mode',()=>{if(data.active)leave();});
  root.querySelectorAll('[data-bundle-brand]').forEach(b=>b.onclick=()=>{data.brand=b.dataset.bundleBrand;el('bundleStatus').textContent='';updateUrl();renderBundle();});
  root.querySelectorAll('[data-bundle-size]').forEach(b=>b.onclick=()=>{data.size=b.dataset.bundleSize;el('bundleStatus').textContent='';updateUrl();renderBundle();});
  root.querySelectorAll('[data-bundle-output]').forEach(b=>b.onclick=()=>{data.mono=b.dataset.bundleOutput==='mono';el('bundleStatus').textContent='';updateUrl();renderBundle();});
  el('bundlePrint').onclick=()=>output(true);el('bundleDownload').onclick=()=>output(false);
  for(const [id,forPrint]of [['printTop',true],['downloadTop',false]])el(id).addEventListener('click',e=>{if(data.active){e.preventDefault();e.stopImmediatePropagation();output(forPrint);}},true);
  window.addEventListener('resize',resize);document.fonts.ready.then(()=>{if(data.active)resize();});
  window.bundleStudio={get active(){return data.active;},syncButtons,preparePrint:prepare,leave};
  if(params.get('view')==='bundle')enter();
})();
